package selecteddiag;

import java.nio.file.*;
import java.util.*;
import org.eclipse.mat.collect.*;
import org.eclipse.mat.inspections.collectionextract.*;
import org.eclipse.mat.query.*;
import org.eclipse.mat.query.annotations.*;
import org.eclipse.mat.query.results.TextResult;
import org.eclipse.mat.snapshot.*;
import org.eclipse.mat.snapshot.model.*;
import org.eclipse.mat.util.IProgressListener;

/** Read-only, source-bound census for c98d12582. No evaluator code runs in the target JVM. */
@CommandName("selected_memory_census") @Name("Selected-change stores and metadata census")
public final class SelectedMemoryCensus implements IQuery {
    @Argument public ISnapshot snapshot;
    @Argument public String output;
    @Argument(isMandatory=false) public String phase="probe";
    @Argument(isMandatory=false) public boolean retained=false;
    private static final String AP="org.opentaint.dataflow.bidi.ap.",
        ST="org.opentaint.dataflow.bidi.store.", EN="org.opentaint.dataflow.bidi.engine.",
        JV="org.opentaint.dataflow.jvm.bidi.interp.";
    private final Map<String,Object> result=new LinkedHashMap<>();
    private final HashMapIntObject<Set<String>> fields=new HashMapIntObject<>();
    private final HashMapIntObject<String> enumNames=new HashMapIntObject<>();
    private final HashMapIntObject<String> methodNames=new HashMapIntObject<>();
    private IProgressListener listener;
    private long visited;

    private void tick() {
        if ((++visited & 65535)==0) {
            if (listener.isCanceled()) throw new IllegalStateException("Census cancelled");
            if ((visited & 1048575)==0) System.err.println("SELECTED_CENSUS phase="+phase+" visited="+visited);
        }
    }
    private Object f(IObject o,String name) throws Exception {
        if (o==null) throw new IllegalStateException("Null owner of field "+name);
        int id=o.getClazz().getObjectId(); Set<String> names=fields.get(id);
        if(names==null) {
            names=new HashSet<>();
            for(IClass c=o.getClazz();c!=null;c=c.getSuperClass())
                for(FieldDescriptor d:c.getFieldDescriptors()) names.add(d.getName());
            fields.put(id,names);
        }
        if(!names.contains(name)) throw new IllegalStateException("Schema mismatch: "+cls(o)+"."+name);
        return o.resolveValue(name);
    }
    private Object optional(IObject o,String name) throws Exception {
        if(o==null)return null;
        try{return f(o,name);}catch(IllegalStateException e){return null;}
    }
    private static IObject obj(Object v){return (IObject)v;}
    private static String cls(IObject v){return v==null?"null":v.getClazz().getName();}
    private static long number(Object v){return ((Number)v).longValue();}
    private static int id(IObject v){return v==null?-1:v.getObjectId();}
    private static String text(Object v){
        if(v instanceof IObject){IObject o=(IObject)v;String n=o.getClassSpecificName();return n==null?o.getDisplayName():n;}
        return String.valueOf(v);
    }
    private String en(Object value) throws Exception {
        IObject o=obj(value);String s=enumNames.get(o.getObjectId());
        if(s==null){s=text(f(o,"name"));enumNames.put(o.getObjectId(),s);}return s;
    }
    private int[] ids(String name) throws Exception {
        Collection<IClass> cs=snapshot.getClassesByName(name,false);
        if(cs==null)return new int[0];int n=0;
        for(IClass c:cs)n=Math.addExact(n,c.getNumberOfObjects());
        int[] out=new int[n];int at=0;
        for(IClass c:cs){int[] a=c.getObjectIds();System.arraycopy(a,0,out,at,a.length);at+=a.length;}
        return out;
    }
    private Iterable<Map.Entry<IObject,IObject>> map(IObject o) throws Exception {
        ExtractedMap m=CollectionExtractionUtils.extractMap(o);
        if(m==null||!m.hasSize())throw new IllegalStateException("Map decoder missing: "+cls(o));
        if(m.size()==0)return Collections.emptyList();
        if(!m.hasExtractableContents())throw new IllegalStateException("Map entries missing: "+cls(o));
        return m;
    }
    private int mapSize(IObject o) throws Exception {
        ExtractedMap m=CollectionExtractionUtils.extractMap(o);
        if(m==null||!m.hasSize())throw new IllegalStateException("Map size decoder missing: "+cls(o));
        return m.size();
    }
    private AbstractExtractedCollection<?,?> collection(IObject o) throws Exception {
        AbstractExtractedCollection<?,?> c=CollectionExtractionUtils.extractCollection(o);
        if(c==null||!c.hasSize())throw new IllegalStateException("Collection decoder missing: "+cls(o));
        return c;
    }
    private int[] contents(IObject o) throws Exception {
        AbstractExtractedCollection<?,?> c=collection(o);
        if(c.size()==0)return new int[0];
        if(!c.hasExtractableContents())throw new IllegalStateException("Collection entries missing: "+cls(o));
        int[] a=c.extractEntryIds();
        if(a.length!=c.size())throw new IllegalStateException("Collection size mismatch: "+cls(o));
        return a;
    }
    private int footprintSize(IObject o) throws Exception {
        if(!cls(o).equals("kotlin.collections.builders.SetBuilder"))return collection(o).size();
        // Kotlin 2.1.20 SetBuilder delegates size to MapBuilder. Check live slots too.
        IObject backing=obj(f(o,"backing"));
        if(!cls(backing).equals("kotlin.collections.builders.MapBuilder"))throw new IllegalStateException("Unknown SetBuilder backing "+cls(backing));
        int size=(int)number(f(backing,"size")),length=(int)number(f(backing,"length"));
        int[] presence=ints(obj(f(backing,"presenceArray")));int live=0;
        if(size<0||length<0||size>length||length>presence.length)throw new IllegalStateException("Invalid SetBuilder size/length");
        for(int i=0;i<length;i++)if(presence[i]>=0)live++;
        if(live!=size)throw new IllegalStateException("SetBuilder live slot count mismatch");
        return size;
    }
    private static long[] refs(IObject o){return o==null?new long[0]:((IObjectArray)o).getReferenceArray();}
    private IObject at(long address) throws Exception {return address==0?null:snapshot.getObject(snapshot.mapAddressToId(address));}
    private int[] ints(IObject o){return o==null?new int[0]:(int[])((IPrimitiveArray)o).getValueArray();}
    private int[] marks(IObject o) throws Exception {return ints(obj(f(o,"data")));}
    private String base(IObject o) throws Exception {
        String c=cls(o);String kind=c.substring(c.lastIndexOf('$')+1);
        if(kind.equals("LocalVar")||kind.equals("Argument"))return kind+":"+number(f(o,"idx"));
        if(kind.equals("Constant"))return kind+":"+text(f(o,"typeName"))+":"+text(f(o,"value"));
        if(kind.equals("CleanerTemporary"))throw new IllegalStateException("Temporary base persisted in an analyzer store");
        return kind;
    }
    private static String family(String base){return base.equals("ClassStatic")?"S":base.equals("Zero")?"Z":"NS";}
    private String methodObject(IObject m) throws Exception {
        if(m==null)return "?";String cached=methodNames.get(m.getObjectId());if(cached!=null)return cached;
        IObject info=obj(optional(m,"methodInfo"));Object name=info==null?optional(m,"name"):optional(info,"name");
        Object desc=info==null?optional(m,"description"):optional(info,"desc");
        IObject c=obj(optional(m,"enclosingClass"));Object cn=optional(c,"name");
        if(cn==null)cn=optional(obj(optional(c,"classSource")),"className");
        if(cn==null){IObject ci=obj(optional(c,"cachedInfo"));if(ci==null)ci=obj(optional(c,"classInfo"));cn=optional(ci,"name");}
        cached=text(cn)+"#"+text(name)+text(desc);methodNames.put(m.getObjectId(),cached);return cached;
    }
    private IObject keyMethod(IObject key) throws Exception {
        IObject statement=obj(f(key,"statement")),loc=obj(optional(statement,"location"));
        IObject m=obj(optional(loc,"method"));return m==null?obj(optional(statement,"method")):m;
    }
    private String keyName(IObject key) throws Exception {IObject m=keyMethod(key);return m==null?key.getDisplayName():methodObject(m);}
    private static void inc(Map<String,Long> out,String key,long n){out.merge(key,n,Math::addExact);}
    private static final class Top {
        final String key;final int max;final PriorityQueue<Map<String,Object>> rows;
        Top(String key,int max){this.key=key;this.max=max;rows=new PriorityQueue<>(Comparator.comparingLong(r->number(r.get(key))));}
        void add(Map<String,Object> row){rows.add(row);if(rows.size()>max)rows.remove();}
        List<Map<String,Object>> get(){List<Map<String,Object>> out=new ArrayList<>(rows);out.sort((a,b)->Long.compare(number(b.get(key)),number(a.get(key))));return out;}
    }
    private void checkpoint(String done) throws Exception {
        result.put("lastCompletedPhase",done);result.put("visited",visited);
        Files.writeString(Path.of(output+".partial.json"),json(result)+"\n");
        System.err.println("SELECTED_CENSUS completed="+done+" visited="+visited);
    }

    private final class Initial {
        final IObject original;final String base,scope,kind,tail;final int[] path,exclusion;final int atom;
        Initial(IObject p) throws Exception {
            original=p;base=SelectedMemoryCensus.this.base(obj(f(p,"base")));tail=en(f(p,"tail"));
            path=ints(obj(f(p,"pathData")));exclusion=exclusion(obj(f(p,"exclusion")));
            IObject mark=obj(f(p,"mark"));boolean flow=cls(mark).equals(AP+"MarkSlot$Star");
            kind=flow?"FLOW":"TAINT";scope=family(base)+"/"+kind;atom=flow?-1:(int)number(f(mark,"mark"));
        }
    }
    private int[] exclusion(IObject o) throws Exception {
        if(cls(o).equals(AP+"ExclusionSet$Empty"))return new int[0];
        if(!cls(o).equals(AP+"ExclusionSet$Concrete"))throw new IllegalStateException("Unknown exclusion: "+cls(o));
        return ints(obj(f(o,"data")));
    }
    private String premiseScope(IObject p) throws Exception {
        if(cls(p).equals(AP+"InitialAp"))return new Initial(p).scope;
        if(!cls(p).equals(AP+"PremiseSet"))throw new IllegalStateException("Unknown premise: "+cls(p));
        TreeSet<String> types=new TreeSet<>();for(long r:refs(obj(f(p,"data"))))types.add(new Initial(at(r)).scope);
        return "ND"+types;
    }
    private boolean emptyLeaf(IObject leaf,boolean flow) throws Exception {
        return flow?en(leaf).equals("NONE"):marks(obj(f(leaf,"exact"))).length==0&&marks(obj(f(leaf,"any"))).length==0;
    }
    private static boolean one(int[] values,int expected){return values.length==1&&values[0]==expected;}
    private boolean singlePath(IObject root,Initial initial,boolean flow) throws Exception {
        IObject node=root;
        for(int depth=0;;depth++) {
            IObject leaf=obj(f(node,"leaf"));long[] children=refs(obj(f(node,"childData")));
            if(depth==initial.path.length) {
                if(children.length!=0)return false;
                if(flow)return en(leaf).equals("LEAF");
                int[] ex=marks(obj(f(leaf,"exact"))),any=marks(obj(f(leaf,"any")));
                return initial.tail.equals("EXACT")?one(ex,initial.atom)&&any.length==0:ex.length==0&&one(any,initial.atom);
            }
            if(!emptyLeaf(leaf,flow)||children.length!=1)return false;
            int[] access=ints(obj(f(node,"accessorData")));
            if(access.length!=1||access[0]!=initial.path[depth])return false;
            node=at(children[0]);
        }
    }
    /** Empty string means exact initial fact image, independent of NORMAL/DEMAND and protection. */
    private String identityReason(Initial initial,IObject fact) throws Exception {
        if(initial==null)return "ND_PREMISE";
        boolean flow=cls(fact).equals(AP+"FlowTree");
        if(!cls(fact).equals(AP+"TaintTree")&&!flow)throw new IllegalStateException("Unexpected fact: "+cls(fact));
        if(!initial.kind.equals(flow?"FLOW":"TAINT"))return "KIND";
        if(!initial.base.equals(base(obj(f(fact,"base")))))return "BASE";
        if(!Arrays.equals(initial.exclusion,exclusion(obj(f(fact,"exclusion")))))return "FIELD_EXCLUSION";
        String expectedTail=!flow&&initial.tail.equals("EXACT")?"ANY_TAINT":initial.tail;
        if(!expectedTail.equals(en(f(fact,flow?"tail":"anyTail"))))return "TAIL";
        if(flow&&marks(obj(f(obj(f(fact,"markExclusion")),"atoms"))).length!=0)return "MARK_EXCLUSION";
        return singlePath(obj(f(fact,"root")),initial,flow)?"":"PATH_OR_MARK_SET";
    }

    private static final class Cell {
        long headers,identity,protectedIdentity,control;
    }
    private Cell cell(IObject group,Initial initial,String scope,Map<String,Long> stats,
                      Map<String,Long> reasons,SetInt uniqueHeaders,SetInt uniqueRoots) throws Exception {
        Cell c=new Cell();boolean[] reach=(boolean[])((IPrimitiveArray)f(group,"reach")).getValueArray();
        for(boolean bit:reach)if(bit)c.control++;
        for(String kind:new String[]{"flow","taint"})for(Map.Entry<IObject,IObject> e:map(obj(f(group,kind)))) {
            long[] layers=refs(obj(f(e.getValue(),"trees")));
            if(layers.length!=2)throw new IllegalStateException("Unexpected layer count");
            for(long listAddress:layers)for(int factId:contents(at(listAddress))) {
                IObject fact=snapshot.getObject(factId);c.headers++;
                String key=scope+"=>"+family(base(obj(f(fact,"base"))))+"/"+kind.toUpperCase(Locale.ROOT)+"/"+en(f(fact,"layer"));
                inc(stats,"headers/"+key,1);inc(stats,"logicalHeaderShallowBytes/"+key,fact.getUsedHeapSize());
                String why=identityReason(initial,fact);
                if(why.isEmpty()) {
                    c.identity++;inc(stats,"literalIdentityHeaders/"+key,1);
                    if(kind.equals("taint")&&f(fact,"nonSubsumable")!=null){c.protectedIdentity++;inc(stats,"protectedIdentityHeaders/"+key,1);}
                    if(uniqueHeaders.add(factId))inc(stats,"physicalLiteralIdentityHeaderShallowBytes",fact.getUsedHeapSize());
                    uniqueRoots.add(obj(f(fact,"root")).getObjectId());
                } else inc(reasons,scope+"/"+why,1);
                tick();
            }
        }
        return c;
    }
    private void methods() throws Exception {
        Map<String,Long> stats=new TreeMap<>(),reasons=new TreeMap<>();
        SetInt uniqueIdentityHeaders=new SetInt(),uniqueIdentityRoots=new SetInt();
        Top top=new Top("occupiedCells",50),staticTop=new Top("staticIdentityOnlyCells",50);
        int[] stores=ids(ST+"MethodEdgeStore");long scalar=0,packed=0,underConstruction=0;
        for(int storeId:stores) {
            IObject store=snapshot.getObject(storeId);if(f(store,"packed")!=null){packed++;continue;}
            IObject groups=obj(f(store,"groups"));if(groups==null){underConstruction++;continue;}scalar++;
            long occupied=0,identities=0,staticIdentity=0,staticPremises=0,headers=0;
            SetInt staticSites=new SetInt();
            for(Map.Entry<IObject,IObject> e:map(groups)) {
                IObject premise=e.getKey();Initial initial=cls(premise).equals(AP+"InitialAp")?new Initial(premise):null;
                String scope=initial==null?premiseScope(premise):initial.scope;
                IObjectArray array=(IObjectArray)e.getValue();
                inc(stats,"premiseArrays/"+scope,1);inc(stats,"arraySlots/"+scope,array.getLength());
                inc(stats,"arrayShallowBytes/"+scope,array.getUsedHeapSize());
                if(initial!=null&&initial.base.equals("ClassStatic"))staticPremises++;
                int atIndex=0;
                for(long address:array.getReferenceArray()) {
                    if(address!=0) {
                        occupied++;inc(stats,"occupiedCells/"+scope,1);IObject group=at(address);
                        inc(stats,"logicalConclusionGroupShallowBytes/"+scope,group.getUsedHeapSize());
                        Cell c=cell(group,initial,scope,stats,reasons,uniqueIdentityHeaders,uniqueIdentityRoots);headers+=c.headers;
                        if(c.identity>0)inc(stats,"cellsWithLiteralIdentity/"+scope,1);
                        if(c.identity>0&&c.identity==c.headers&&c.control==0) {
                            identities++;inc(stats,"literalIdentityOnlyCells/"+scope,1);
                            if(initial!=null&&initial.base.equals("ClassStatic")){staticIdentity++;staticSites.add(atIndex);}
                        } else inc(stats,"otherOrMixedCells/"+scope,1);
                    }
                    atIndex++;
                }
                tick();
            }
            long reachPremises=0,reachMemberships=0;
            for(Map.Entry<IObject,IObject> e:map(obj(f(store,"reach")))) {
                String scope=premiseScope(e.getKey());reachPremises++;
                for(long address:refs(e.getValue())) {
                    IObject bits=at(address);long n=0;
                    for(long word:(long[])((IPrimitiveArray)f(bits,"words")).getValueArray())n+=Long.bitCount(word);
                    reachMemberships+=n;inc(stats,"reachPointMemberships/"+scope,n);
                }
            }
            inc(stats,"reachPremiseArrays",reachPremises);inc(stats,"reachPointMemberships",reachMemberships);
            IObject key=obj(f(store,"method"));Map<String,Object> row=new LinkedHashMap<>();
            row.put("storeId",storeId);row.put("methodKeyId",key.getObjectId());row.put("method",keyName(key));
            row.put("occupiedCells",occupied);row.put("headerOccurrences",headers);row.put("identityOnlyCells",identities);
            row.put("staticPremises",staticPremises);row.put("staticIdentityOnlyCells",staticIdentity);
            row.put("staticIdentityStatementIndices",staticSites.size());row.put("staticPremiseTimesIdentitySites",staticPremises*staticSites.size());
            top.add(row);staticTop.add(row);tick();
        }
        Map<String,Object> out=new LinkedHashMap<>();out.put("stores",stores.length);out.put("scalarStores",scalar);
        out.put("packedStoresSkipped",packed);out.put("underConstructionStores",underConstruction);out.put("counts",stats);
        out.put("nonIdentityReasonsByHeaderOccurrence",reasons);out.put("physicalLiteralIdentityHeaders",uniqueIdentityHeaders.size());
        out.put("physicalLiteralIdentityTrieRoots",uniqueIdentityRoots.size());out.put("topOccupiedCells",top.get());out.put("topStaticIdentityCells",staticTop.get());
        out.put("definition","Literal identity means same initial base, entire single path, tail, field exclusion and mark image; FLOW has empty mark exclusion. Layer and protection are reported separately. A mixed tree which merely contains an identity path is not literal identity.");
        result.put("methodStores",out);
    }

    private final class Owner {
        final int actor,key,run;final String method;
        Owner(IObject a) throws Exception {
            actor=a.getObjectId();IObject k=obj(f(a,"key"));key=k.getObjectId();method=keyName(k);
            IObject context=obj(f(a,"runContext"));run=context==null?0:(int)number(f(obj(f(context,"config")),"index"));
        }
        Map<String,Object> fields(){return Map.of("actorId",actor,"methodKeyId",key,"method",method,"activeRunIndexOrZeroIfFrozen",run);}
    }
    private void caches() throws Exception {
        HashMapIntObject<Owner> owners=new HashMapIntObject<>();long frozen=0,active=0;
        for(int actorId:ids(EN+"RunMethodAnalyzer")) {
            IObject a=snapshot.getObject(actorId),context=obj(f(a,"runContext"));if(context==null){frozen++;continue;}
            active++;IObject cache=obj(f(context,"delivery"));if(cache!=null)owners.put(cache.getObjectId(),new Owner(a));
        }
        Map<String,Long> counts=new TreeMap<>(),widths=new TreeMap<>();Top top=new Top("queryCells",50);int[] cacheIds=ids(EN+"CfgDeliveryCache");
        for(int cacheId:cacheIds) {
            IObject c=snapshot.getObject(cacheId);IObjectArray rows=(IObjectArray)f(c,"rows");
            if(rows==null){inc(counts,"underConstruction",1);continue;}
            long populatedStarts=0,queryCells=0,empty=0,destinations=0,frontierBytes=0,maxWidth=0;
            inc(counts,"outerRowsArrayShallowBytes",rows.getUsedHeapSize());inc(counts,"outerRowsSlots",rows.getLength());
            for(long address:rows.getReferenceArray())if(address!=0) {
                IObject row=at(address);populatedStarts++;inc(counts,"rowMapShallowBytes",row.getUsedHeapSize());
                int actual=0;
                for(Map.Entry<IObject,IObject> e:map(row)) {
                    actual++;queryCells++;IPrimitiveArray frontier=(IPrimitiveArray)e.getValue();int n=frontier.getLength();
                    if(n==0)empty++;destinations+=n;maxWidth=Math.max(maxWidth,n);frontierBytes+=frontier.getUsedHeapSize();
                    inc(widths,Integer.toString(n),1);tick();
                }
                if(actual!=mapSize(row))throw new IllegalStateException("CFG cache map count mismatch");
            }
            inc(counts,"populatedStarts",populatedStarts);inc(counts,"queryCells",queryCells);inc(counts,"emptyFrontiers",empty);
            inc(counts,"destinations",destinations);inc(counts,"frontierArraysShallowBytes",frontierBytes);
            if(owners.get(cacheId)==null)inc(counts,"cachesWithoutActiveActorOwner",1);
            Map<String,Object> row=new LinkedHashMap<>();row.put("cacheId",cacheId);Owner owner=owners.get(cacheId);
            if(owner!=null)row.putAll(owner.fields());row.put("queryCells",queryCells);row.put("populatedStarts",populatedStarts);
            row.put("emptyFrontiers",empty);row.put("destinations",destinations);row.put("maxWidth",maxWidth);row.put("frontierArraysShallowBytes",frontierBytes);
            if(retained)row.put("retainedBytesIndividualNonAdditive",snapshot.getRetainedHeapSize(cacheId));top.add(row);tick();
        }
        Map<String,Object> out=new LinkedHashMap<>();out.put("cacheCount",cacheIds.length);out.put("activeActors",active);out.put("frozenActors",frozen);
        out.put("counts",counts);out.put("frontierWidthHistogram",widths);out.put("topByQueryCells",top.get());
        if(retained)out.put("allCacheDominatorUnionMinRetainedBytes",snapshot.getMinRetainedSize(cacheIds,listener));
        result.put("cfgDeliveryCaches",out);
    }

    private static final class PhysicalForms {
        final SetInt forward=new SetInt(),backward=new SetInt();long contexts,forwardCopies,backwardCopies,members;
    }
    private void forms() throws Exception {
        HashMapIntObject<PhysicalForms> physical=new HashMapIntObject<>();Map<String,Long> totals=new TreeMap<>();Top top=new Top("cachedInstructionCopies",50);
        for(int formId:ids(JV+"JIRMethodForms")) {
            IObject forms=snapshot.getObject(formId),entry=obj(f(forms,"entry"));if(entry==null){inc(totals,"underConstruction",1);continue;}
            IObject method=obj(f(entry,"method"));PhysicalForms p=physical.get(method.getObjectId());
            if(p==null){p=new PhysicalForms();physical.put(method.getObjectId(),p);}p.contexts++;
            for(String field:new String[]{"forwardBases","backwardBases"}) {
                IObject cached=obj(f(forms,field));if(cached==null){inc(totals,field+"/uninitializedMaps",1);continue;}
                inc(totals,field+"/maps",1);inc(totals,field+"/mapShallowBytes",cached.getUsedHeapSize());long copies=0,members=0;
                for(Map.Entry<IObject,IObject> e:map(cached)) {
                    int key=(int)number(f(e.getKey(),"value"));
                    (field.equals("forwardBases")?p.forward:p.backward).add(key);copies++;
                    int size=footprintSize(e.getValue());members+=size;
                    inc(totals,field+"/setShallowBytes",e.getValue().getUsedHeapSize());tick();
                }
                if(copies!=mapSize(cached))throw new IllegalStateException("Footprint map count mismatch");
                inc(totals,field+"/cachedInstructionCopies",copies);inc(totals,field+"/baseMembershipCopies",members);p.members+=members;
                if(field.equals("forwardBases"))p.forwardCopies+=copies;else p.backwardCopies+=copies;
            }
            tick();
        }
        long contexts=0,uniqueSlots=0;
        for(int methodId:physical.getAllKeys()) {
            PhysicalForms p=physical.get(methodId);contexts+=p.contexts;uniqueSlots+=p.forward.size()+p.backward.size();
            Map<String,Object> row=new LinkedHashMap<>();row.put("physicalMethodId",methodId);row.put("method",methodObject(snapshot.getObject(methodId)));
            row.put("contextForms",p.contexts);row.put("forwardCachedCopies",p.forwardCopies);row.put("backwardCachedCopies",p.backwardCopies);
            row.put("distinctForwardInstructionKeys",p.forward.size());row.put("distinctBackwardInstructionKeys",p.backward.size());
            row.put("cachedInstructionCopies",p.forwardCopies+p.backwardCopies);row.put("baseMembershipCopies",p.members);
            row.put("duplicateInstructionKeyCopies",p.forwardCopies+p.backwardCopies-p.forward.size()-p.backward.size());top.add(row);
        }
        Map<String,Object> out=new LinkedHashMap<>();out.put("physicalMethods",physical.size());out.put("contextForms",contexts);out.put("distinctMethodDirectionInstructionKeys",uniqueSlots);
        out.put("counts",totals);out.put("topByCachedCopies",top.get());
        out.put("definition","A duplicate key means multiple contextual JIRMethodForms cached the same common-method/direction/instruction. Equal footprint content is source-derived, not asserted from object identity.");
        result.put("jvmRelevanceFootprints",out);
    }

    private Map<String,Object> classCounts(String[] names) throws Exception {
        Map<String,Object> out=new LinkedHashMap<>();
        for(String name:names) {
            Collection<IClass> classes=snapshot.getClassesByName(name,false);long count=0,bytes=0;
            if(classes!=null)for(IClass c:classes){count+=c.getNumberOfObjects();bytes+=c.getNumberOfObjects()*c.getHeapSizePerInstance();}
            out.put(name,Map.of("loadedClasses",classes==null?0:classes.size(),"instances",count,"shallowBytes",bytes));
        }return out;
    }
    private void indexes() throws Exception {
        Map<String,Long> counts=new TreeMap<>();Map<String,Long> shape=new TreeMap<>();int[] indexes=ids(ST+"StaticOutputOrdinals");
        for(int indexId:indexes) {
